"""Dataset card (README.md with Hugging Face YAML front matter) generated from the built dataset's metadata."""

from __future__ import annotations

import json
from pathlib import Path

import pandas as pd
import yaml

from robodata.config import CONFIG_DIR, load_robot

SOURCE_NOTES = {
    "ur5_catheter": ("giakhuyendihoc/catheter_force_depth_eef", "apache-2.0",
                     "Real UR5 teleoperated catheter/cable insertion (3 RGB + 3 depth cameras, wrist F/T, SpaceMouse target pose)."),
    "ur5_sim": ("generated by robodata.sim (MuJoCo)", "apache-2.0",
                "Simulated twin of the insertion cell: UR5 kinematics, held peg, hole block, 3 RGB-D cameras, wrist F/T, "
                "scripted human-like teleoperator, 6 randomised scenes."),
    "franka_droid": ("lerobot/droid_100", "mit", "DROID Franka Panda subset (2 exterior + 1 wrist camera)."),
}


def _table(df: pd.DataFrame) -> str:
    return df.to_markdown(index=False)


def write_dataset_card(root: str | Path) -> Path:
    root = Path(root)
    info = json.loads((root / "meta" / "info.json").read_text())
    rd = root / "meta" / "robodata"
    recipe = json.loads((rd / "recipe.json").read_text())
    eps = pd.read_parquet(rd / "episodes.parquet")
    splits = json.loads((rd / "splits.json").read_text())
    robots = sorted(eps.robot_id.unique())
    licenses = sorted({SOURCE_NOTES.get(r, ("", recipe.get("license", "other"), ""))[1] for r in robots})
    front = {
        "license": licenses[0] if len(licenses) == 1 else "other",
        "task_categories": ["robotics"],
        "tags": ["LeRobot", "robodata", "teleoperation", "imitation-learning"]
                + (["sim-and-real"] if eps.is_sim.nunique() > 1 else []) + [info.get("robot_type", "")],
        "configs": [{"config_name": "default", "data_files": "data/*/*.parquet"}],
    }
    feats = []
    for k, f in info["features"].items():
        extra = "depth (uint16 mm, 12-bit quantised HEVC)" if (f.get("info") or {}).get("is_depth_map") else ""
        names = f.get("names")
        if isinstance(names, list) and f["dtype"] not in ("video", "image"):
            extra = extra or ", ".join(map(str, names))[:90]
        feats.append({"feature": f"`{k}`", "dtype": f["dtype"], "shape": str(f["shape"]), "notes": extra})
    per_split = (eps.groupby(["split", "robot_id", "is_sim"]).agg(episodes=("episode_id", "count"), frames=("frames", "sum"))
                 .reset_index())
    src_rows = [{"robot": r, "source": SOURCE_NOTES.get(r, ("?", "?", ""))[0], "license": SOURCE_NOTES.get(r, ("", "?", ""))[1],
                 "episodes": int((eps.robot_id == r).sum()), "description": SOURCE_NOTES.get(r, ("", "", ""))[2]}
                for r in robots]
    sensor_rows = []
    for r in robots:
        cfg = load_robot(r)
        for s, c in cfg.streams.items():
            sensor_rows.append({"robot": r, "stream": s, "kind": c.kind, "rate_hz": c.rate_hz,
                                "shape": str(c.shape), "ROS topic": f"`{c.topic}`"})
    sync = eps.groupby("robot_id").sync_residual_p95_ms.describe()[["mean", "50%", "max"]].round(2).reset_index()
    phase_cols = [c for c in eps.columns if c.startswith("phase_b") and c.endswith("_err_s")]
    phase_txt = ""
    if phase_cols:
        pe = eps[phase_cols].astype(float).describe().loc[["count", "50%", "mean"]].round(3)
        phase_txt = ("\nPhase boundaries vs the simulator's ground-truth operator phases (seconds; b1 approach->align, "
                     "b2 contact onset vs GT insert start, b3 settle):\n\n" + pe.reset_index().to_markdown(index=False) + "\n")
    cal = sorted(eps.calibration_version.unique())
    cal_txt = []
    for c in cal:
        p = CONFIG_DIR / "calibration" / f"{c}.yaml"
        if p.exists():
            doc = yaml.safe_load(p.read_text())
            errs = {cam: v.get("gt_error") for cam, v in doc["cameras"].items() if v.get("gt_error")}
            cal_txt.append(f"- `{c}` (hash `{doc['content_hash']}`): errors vs simulator ground truth: `{json.dumps(errs)}`")
        else:
            cal_txt.append(f"- `{c}`: no calibration available for this source (flagged as a health warning)")
    usage = f'''```python
from lerobot.datasets.lerobot_dataset import LeRobotDataset

ds = LeRobotDataset("{info.get('repo_id', recipe['repo_id'])}", root="path/to/{root.name}",
                    delta_timestamps={{"action": [i / {info['fps']} for i in range(10)]}})
train_eps = range(*map(int, ds.meta.info["splits"]["train"].split(":")))
frame = ds[0]  # images (C,H,W) float in [0,1], depth (1,H,W) in mm, state/action float32, is_sim, phase_index
```'''
    lines = [
        "---", yaml.safe_dump(front, sort_keys=False).strip(), "---", "",
        f"# {root.name}", "",
        f"{len(eps)} episodes / {int(eps.frames.sum())} frames at {info['fps']} Hz, built with **robodata** "
        f"(record -> sync -> health -> curate -> build). Format: LeRobot `{info['codebase_version']}`; loads directly "
        "with `LeRobotDataset`, no conversion step.", "",
        "## Sources", "", _table(pd.DataFrame(src_rows)), "",
        "Real and simulated episodes share one schema (same feature keys, shapes, units and conventions); "
        "every frame carries `is_sim`.", "",
        "## Features", "", _table(pd.DataFrame(feats)), "",
        "## Splits (no leakage)", "",
        f"Split by `{splits['group_key']}` (whole recording sessions / simulated scenes), stratified by robot and "
        f"real/sim; near-duplicate clusters never straddle splits. LeRobot ranges: `{splits['ranges']}`.", "",
        _table(per_split), "",
        "## Sensors and collection", "", _table(pd.DataFrame(sensor_rows)), "",
        "## Synchronisation", "",
        "Each message keeps its sensor (header) timestamp and the recorder's receive time. Per stream, the sensor "
        "clock is mapped onto the recorder clock with a lower-envelope (one-sided-latency) fit that removes offset "
        "and drift, then the calibrated constant latency is subtracted. Cameras are sampled at the nearest frame "
        "to each training tick, low-dim streams are interpolated (linear / slerp / zero-order hold for commands / "
        "anti-aliased low-pass for 500 Hz F/T). `observation.sync_residual_ms` stores the worst camera-to-tick "
        "residual per frame.", "", "Residual sync error p95 per episode (ms):", "", _table(sync), "",
        "## Calibration", "", *cal_txt, "",
        "## Quality, curation, phases", "",
        f"- health checks: dropped frames, timestamp jumps, clock drift, corrupt / frozen frames, missing modalities, "
        f"NaN / out-of-range values, sync residual; failing episodes are quarantined, not shipped",
        f"- curation summary: `{json.dumps(json.loads((rd / 'curation_summary.json').read_text())['excluded'])}` excluded",
        f"- `phase_index`: unsupervised task-phase segmentation ({', '.join(json.loads((rd / 'phases.json').read_text())['names'])})",
        phase_txt,
        "## Known limitations", "",
        "- The catheter source publishes depth as 8-bit grey video; it is decoded to millimetres assuming a linear 0-2 m "
        "range (relative depth is reliable, absolute scale is an assumption).",
        "- Open-source episodes were re-recorded through a virtual robot that re-applies realistic per-sensor clock "
        "offsets / drift / latency / drops (the source data is already resampled to 30 Hz); sessions for the catheter "
        "source are consecutive blocks of 10 demonstrations (the source has no session metadata).",
        "- LeRobot's depth quantiser clamps invalid (0) depth pixels to `depth_min` (50 mm).",
        "- Real catheter data ships without camera calibration; simulated cameras are calibrated (see above).", "",
        "## Usage", "", usage, "",
        "## Reproducibility", "",
        "Every build is versioned by a content hash manifest (`data/versions/<dataset>/<version>.json`) that also "
        "records the pinned source revisions, config hashes and code version. `robodata verify <dataset>` checks the "
        "bytes on disk against it.", "",
        "## Licence", "",
        "Derived data inherits the licence of its source (see Sources). Simulated data and code: Apache-2.0.",
    ]
    out = root / "README.md"
    out.write_text("\n".join(lines) + "\n")
    return out
